package com.lyrashop.user.entity;import java.util.UUID;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;import jakarta.persistence.*;
@Entity @Table(name="newsletter_subscriptions") public class NewsletterSubscription{@Id @GeneratedValue(strategy=GenerationType.UUID) @JdbcTypeCode(SqlTypes.BINARY) @Column(length=16) private UUID id;@Column(nullable=false,updatable=false)private String email;@Column(name="is_active")private boolean active=true;protected NewsletterSubscription(){}public NewsletterSubscription(String e){email=e;}public void activate(){active=true;}public void deactivate(){active=false;}}
